def model(regime, n, seed):
    rng = np.random.default_rng(seed)
    X, Y = T[int(regime.config["line"])]
    d = np.full(n, float(regime.config["driver"]))
    return pd.DataFrame({"outcome": np.interp(d, X, Y) + rng.normal(0.0, 0.7, n)})
